# MCQ templates per phase
def make_mcqs(day_num, phase_idx):
    """Generate 10 MCQs for a given day based on its phase."""
    mcq_banks = {
        0: [  # HTML & CSS
            ("What does HTML stand for?", ["HyperText Markup Language", "High Tech Modern Language", "HyperTransfer Markup Language", "Home Tool Markup Language"], 0, "HTML stands for HyperText Markup Language."),
            ("Which tag is used for the largest heading?", ["<h6>", "<heading>", "<h1>", "<head>"], 2, "The <h1> tag defines the largest heading."),
            ("What is the correct CSS property to change text color?", ["text-color", "font-color", "color", "foreground-color"], 2, "The 'color' property sets the text color in CSS."),
            ("Which CSS property is used to add space inside an element?", ["margin", "padding", "border", "spacing"], 1, "Padding adds space inside an element, between content and border."),
            ("What does the 'display: flex' property do?", ["Makes element invisible", "Creates a flex container", "Adds flexibility to fonts", "Floats the element"], 1, "display: flex creates a flex container for flexible layouts."),
            ("Which HTML tag is semantic for navigation?", ["<div>", "<nav>", "<menu>", "<links>"], 1, "The <nav> tag is the semantic element for navigation sections."),
            ("How do you make a CSS comment?", ["// comment", "/* comment */", "<!-- comment -->", "# comment"], 1, "CSS comments use /* */ syntax."),
            ("Which property creates rounded corners?", ["corner-radius", "border-radius", "round-corner", "border-round"], 1, "border-radius creates rounded corners in CSS."),
            ("What does 'responsive design' mean?", ["Fast loading", "Adapts to different screen sizes", "Uses animations", "Server-side rendering"], 1, "Responsive design means the layout adapts to different screen sizes."),
            ("Which unit is relative to the parent element's font size?", ["px", "em", "vh", "cm"], 1, "The 'em' unit is relative to the parent element's font size."),
        ],
        1: [  # JavaScript
            ("Which keyword declares a constant in JavaScript?", ["var", "let", "const", "constant"], 2, "The 'const' keyword declares a constant that cannot be reassigned."),
            ("What is the result of typeof null?", ["'null'", "'undefined'", "'object'", "'boolean'"], 2, "typeof null returns 'object' — a known JavaScript quirk."),
            ("Which method adds an element to the end of an array?", ["push()", "append()", "add()", "insert()"], 0, "The push() method adds elements to the end of an array."),
            ("What does === check?", ["Value only", "Type only", "Value and type", "Reference only"], 2, "The === operator checks both value AND type (strict equality)."),
            ("Which array method creates a new array with transformed elements?", ["forEach()", "filter()", "map()", "reduce()"], 2, "map() creates a new array by transforming each element."),
            ("What is a closure?", ["A syntax error", "A function with access to its outer scope", "A way to close the browser", "A loop construct"], 1, "A closure is a function that has access to variables from its outer scope."),
            ("How do you handle errors in async/await?", ["if/else", "try/catch", "error/handle", "promise.error()"], 1, "Use try/catch blocks to handle errors in async/await code."),
            ("What does JSON.parse() do?", ["Converts object to string", "Converts string to object", "Validates JSON", "Creates a new object"], 1, "JSON.parse() converts a JSON string into a JavaScript object."),
            ("Which event fires when a form is submitted?", ["click", "change", "submit", "input"], 2, "The 'submit' event fires when a form is submitted."),
            ("What is the DOM?", ["A programming language", "A tree representation of HTML", "A CSS framework", "A database"], 1, "The DOM is a tree-structured representation of the HTML document."),
        ],
        2: [  # React
            ("What is JSX?", ["A new language", "JavaScript XML syntax extension", "A CSS preprocessor", "A testing framework"], 1, "JSX is a syntax extension that lets you write HTML-like code in JavaScript."),
            ("What hook manages state in a function component?", ["useEffect", "useState", "useContext", "useRef"], 1, "useState is the hook for managing state in function components."),
            ("When does useEffect with an empty dependency array run?", ["Every render", "Only on mount", "Never", "On unmount only"], 1, "useEffect with [] runs only once when the component mounts."),
            ("What are props in React?", ["Global variables", "Read-only inputs to components", "Mutable state", "CSS styles"], 1, "Props are read-only inputs passed from parent to child components."),
            ("How do you conditionally render in JSX?", ["if/else inside JSX", "Ternary operator or &&", "switch statement", "for loop"], 1, "Use ternary operators or && for conditional rendering in JSX."),
            ("What is the virtual DOM?", ["The actual browser DOM", "A lightweight copy of the DOM", "A CSS engine", "A testing tool"], 1, "The virtual DOM is a lightweight JavaScript copy of the actual DOM."),
            ("Which hook handles side effects?", ["useState", "useEffect", "useMemo", "useCallback"], 1, "useEffect handles side effects like data fetching and subscriptions."),
            ("What is component composition?", ["Inheriting from a base component", "Building complex UI from smaller components", "Adding CSS to components", "Testing components"], 1, "Composition means building complex UI by combining smaller components."),
            ("What does key prop do in lists?", ["Adds keyboard shortcuts", "Helps React identify which items changed", "Sets access keys", "Encrypts data"], 1, "The key prop helps React efficiently update lists by identifying items."),
            ("How do you share state between sibling components?", ["Global variables", "Lift state up to parent", "Use localStorage", "Direct DOM manipulation"], 1, "Lift state up to the nearest common parent component."),
        ],
        3: [  # Backend
            ("What does REST stand for?", ["Real-time Event State Transfer", "Representational State Transfer", "Remote Server Technology", "Request-Send-Transfer"], 1, "REST stands for Representational State Transfer."),
            ("Which HTTP method is used to create a resource?", ["GET", "POST", "PUT", "DELETE"], 1, "POST is typically used to create new resources."),
            ("What status code means 'Not Found'?", ["400", "401", "403", "404"], 3, "HTTP 404 means the requested resource was not found."),
            ("What is middleware?", ["Database software", "Code that runs between request and response", "Frontend framework", "Testing tool"], 1, "Middleware is code that processes requests before they reach the endpoint."),
            ("What does CORS stand for?", ["Cross-Origin Resource Sharing", "Client-Origin Request System", "Cross-Object Response Service", "Cache-Origin Resource System"], 0, "CORS stands for Cross-Origin Resource Sharing."),
            ("Which Python type hint means 'returns nothing'?", ["void", "None", "null", "empty"], 1, "In Python, None is used as the return type hint for functions that return nothing."),
            ("What is Pydantic used for?", ["Database ORM", "Data validation and serialization", "Testing", "Deployment"], 1, "Pydantic is used for data validation and serialization in Python."),
            ("What is dependency injection?", ["Installing packages", "Providing dependencies to functions automatically", "Injecting CSS", "A security vulnerability"], 1, "DI is a pattern where dependencies are provided to functions automatically."),
            ("Which HTTP method is idempotent?", ["POST", "PUT", "PATCH (sometimes)", "All of the above"], 1, "PUT is idempotent — calling it multiple times has the same effect as once."),
            ("What format do REST APIs typically use?", ["XML", "JSON", "CSV", "HTML"], 1, "REST APIs typically use JSON for data exchange."),
        ],
        4: [  # Database & Auth
            ("What does SQL stand for?", ["Structured Query Language", "Simple Query Logic", "Server Query Language", "Structured Question Language"], 0, "SQL stands for Structured Query Language."),
            ("What is an ORM?", ["Object-Relational Mapping", "Online Resource Manager", "Optimized Request Method", "Object Reference Model"], 0, "ORM maps database tables to programming language objects."),
            ("What is a foreign key?", ["A primary key from another country", "A field referencing another table's primary key", "An encrypted key", "A deprecated key"], 1, "A foreign key references the primary key of another table."),
            ("Why should you hash passwords?", ["To make them shorter", "To protect them if the database is compromised", "To validate format", "To encrypt the database"], 1, "Hashing protects passwords even if the database is breached."),
            ("What is JWT?", ["Java Web Token", "JSON Web Token", "JavaScript Worker Thread", "Joint Web Technology"], 1, "JWT stands for JSON Web Token, used for stateless authentication."),
            ("What is RBAC?", ["Remote Backup and Cache", "Role-Based Access Control", "Request-Based API Call", "Runtime Binary Access Check"], 1, "RBAC controls access to resources based on user roles."),
            ("What is an index in a database?", ["A table of contents", "A data structure for faster queries", "A primary key", "A backup copy"], 1, "An index is a data structure that speeds up database queries."),
            ("What is a database migration?", ["Moving to a new server", "Version-controlled schema changes", "Backing up data", "Importing CSV files"], 1, "Migrations are version-controlled changes to the database schema."),
            ("What is bcrypt?", ["A database engine", "A password hashing algorithm", "A JavaScript framework", "A CSS preprocessor"], 1, "bcrypt is a password hashing algorithm designed for security."),
            ("What is the purpose of a refresh token?", ["To refresh the page", "To get a new access token without re-login", "To update the database", "To clear the cache"], 1, "Refresh tokens allow getting new access tokens without re-authenticating."),
        ],
        5: [  # Deployment
            ("What is Docker?", ["A programming language", "A containerization platform", "A web framework", "A database"], 1, "Docker is a platform for building and running containerized applications."),
            ("What is CI/CD?", ["Code Integration/Code Delivery", "Continuous Integration/Continuous Deployment", "Container Integration/Container Delivery", "Client Interface/Client Design"], 1, "CI/CD stands for Continuous Integration and Continuous Deployment."),
            ("What is a Dockerfile?", ["A documentation file", "Instructions to build a Docker image", "A configuration for Docker Compose", "A Docker log file"], 1, "A Dockerfile contains instructions for building a Docker image."),
            ("What does Vercel primarily host?", ["Databases", "Frontend and serverless functions", "Email servers", "Game servers"], 1, "Vercel primarily hosts frontend applications and serverless functions."),
            ("What is an environment variable?", ["A JavaScript variable", "A configuration value set outside the code", "A CSS variable", "A database field"], 1, "Environment variables are configuration values set outside the source code."),
            ("What is a health check endpoint?", ["A medical API", "An endpoint that confirms the service is running", "A security scanner", "A performance test"], 1, "A health check endpoint returns a simple response to confirm the service is up."),
            ("What does 'npm run build' typically do?", ["Starts the dev server", "Creates a production-ready bundle", "Runs tests", "Installs dependencies"], 1, "npm run build creates an optimized production build."),
            ("What is the purpose of .env files?", ["To store environment-specific configuration", "To define CSS styles", "To write documentation", "To configure Git"], 0, ".env files store environment-specific configuration variables."),
            ("What is a reverse proxy?", ["A proxy that blocks requests", "A server that forwards requests to backend services", "A caching mechanism", "A firewall"], 1, "A reverse proxy sits in front of servers and forwards client requests."),
            ("Why use multi-stage Docker builds?", ["To run multiple apps", "To create smaller final images", "To build faster", "To add more features"], 1, "Multi-stage builds produce smaller images by separating build and runtime."),
        ],
    }
    bank = mcq_banks.get(phase_idx, mcq_banks[0])
    return bank[:10]

def main():
    conn = sqlite3.connect(DB_PATH)
    cur = conn.cursor()

    # Clear existing data
    cur.execute("DELETE FROM mcq_questions")
    cur.execute("DELETE FROM days")
    cur.execute("DELETE FROM phases")
    conn.commit()
    print("Cleared existing content.")

    now = datetime.now(timezone.utc).isoformat()

    # Insert phases
    phase_ids = {}
    for i, p in enumerate(PHASES):
        pid = str(uuid.uuid4())
        phase_ids[i] = pid
        cur.execute(
            "INSERT INTO phases (id, name, description, tagline, accent_color, skills_list, display_order, is_published, created_at) VALUES (?,?,?,?,?,?,?,?,?)",
            (pid, p["name"], f"Phase {i+1}: {p['tagline']}", p["tagline"], p["color"], json.dumps(p["skills"]), i+1, 1, now),
        )
    print(f"Inserted {len(PHASES)} phases.")

    # Insert days and MCQs
    for d in DAYS:
        day_num = d["day"]
        phase_idx = (day_num - 1) // 5
        phase_id = phase_ids[phase_idx]
        day_id = str(uuid.uuid4())

        cur.execute(
            """INSERT INTO days (id, phase_id, day_number, title, estimated_time, lesson_content,
            assignment_prompt, assignment_type, starter_code, reference_solution, language,
            is_published, is_draft, version, created_at, updated_at)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (day_id, phase_id, day_num, d["title"], d["time"], d["lesson"],
             d["assignment"], d["type"], d["starter"], None, d["lang"],
             1, 0, 1, now, now),
        )

        # Insert MCQs
        mcqs = make_mcqs(day_num, phase_idx)
        for qi, (q, opts, correct, explanation) in enumerate(mcqs):
            cur.execute(
                "INSERT INTO mcq_questions (id, day_id, question_text, options, correct_option_index, explanation, display_order) VALUES (?,?,?,?,?,?,?)",
                (str(uuid.uuid4()), day_id, q, json.dumps(opts), correct, explanation, qi + 1),
            )

        print(f"  Day {day_num}: {d['title']} + {len(mcqs)} MCQs")

    conn.commit()
    conn.close()
    print(f"\nDone! Seeded {len(DAYS)} days with MCQs.")

if __name__ == "__main__":
    main()
